def llama_thread_count(*, backend: str = "cuda") -> int:
    """Число потоков llama-server.

    На GPU основная нагрузка на CUDA; CPU-потоки нужны для пре/пост-обработки.
    Переопределение: LLAMA_THREADS в окружении хоста.
    """
    if env := os.environ.get("LLAMA_THREADS"):
        return max(1, int(env))
    if backend == "cuda":
        return 4
    cpus = os.cpu_count() or 4
    return max(1, cpus - 1)


def gpu_docker_available() -> bool:
    """Проверка: docker run --gpus all видит NVIDIA GPU."""
    r = docker("run", "--rm", "--gpus", "all",
               "nvidia/cuda:12.1.0-base-ubuntu22.04", "nvidia-smi", "-L",
               check=False, timeout=120)
    return r.returncode == 0

